#include <M5Unified.h>
#include <esp_heap_caps.h>

extern "C" {
#include "core/canvas.h"
#include "hacks/registry.h"
#include "runner/hack_runner.h"
}

static const int kSize = 466;
static const uint32_t kSliceUs = 10000;
static const uint32_t kStatsEveryMs = 5000;

static Canvas canvas;
static HackRunner *runner;
static uint32_t frames;
static uint32_t statsAt;

static void halt(const char *msg) {
  Serial.println(msg);
  M5.Display.fillScreen(0x000000);
  M5.Display.setTextColor(0xFFFFFF);
  M5.Display.setTextDatum(middle_center);
  M5.Display.drawString(msg, M5.Display.width() / 2, M5.Display.height() / 2);
  for (;;) delay(1000);
}

static void printStats(const char *tag) {
  Serial.printf("%s %s fps=%.1f heap=%u psram=%u\n", tag,
                g_hacks[runner_index(runner)]->name,
                frames * 1000.0f / kStatsEveryMs, (unsigned)ESP.getFreeHeap(),
                (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
}

static void pollButtons() {
  bool switched = false;
  if (M5.BtnA.wasPressed()) {
    runner_next(runner);
    switched = true;
  }
  if (M5.BtnB.wasPressed()) {
    runner_prev(runner);
    switched = true;
  }
  if (switched) {
    Serial.printf("switch -> %s heap=%u psram=%u\n",
                  g_hacks[runner_index(runner)]->name,
                  (unsigned)ESP.getFreeHeap(),
                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
    frames = 0;
    statsAt = millis();
  }
}

void setup() {
  auto cfg = M5.config();
  M5.begin(cfg);
  Serial.begin(115200);
  M5.Display.setSwapBytes(false);

  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
    halt("PSRAM alloc failed");
  runner = runner_create(&canvas);
  if (!runner || runner_start(runner, 0) != 0) halt("hack start failed");
  printStats("boot");
  statsAt = millis();
}

void loop() {
  M5.update();
  pollButtons();

  unsigned long delayUs = runner_step(runner);
  M5.Display.pushImage(0, 0, kSize, kSize, canvas.px);
  frames++;

  uint32_t waitedUs = 0;
  while (waitedUs < delayUs) {
    uint32_t slice = delayUs - waitedUs < kSliceUs ? delayUs - waitedUs : kSliceUs;
    delayMicroseconds(slice);
    waitedUs += slice;
    M5.update();
    pollButtons();
  }

  if (millis() - statsAt >= kStatsEveryMs) {
    printStats("run");
    frames = 0;
    statsAt = millis();
  }
}
#include "runner/hack_runner.h"

#include <stdlib.h>

#include "hacks/registry.h"
#include "x11shim/xshim.h"

#define RUNNER_WINDOW ((Window)1)

struct HackRunner {
  Canvas *canvas;
  Display *dpy;
  const HackEntry *const *hacks;
  int count;
  int index;
  void *closure;
  int running;
};

HackRunner *runner_create_with(Canvas *canvas, const HackEntry *const *hacks,
                               int count) {
  HackRunner *r = (HackRunner *)calloc(1, sizeof(*r));
  if (!r) return NULL;
  r->canvas = canvas;
  r->dpy = xshim_open_display(canvas);
  r->hacks = hacks;
  r->count = count;
  if (!r->dpy) {
    free(r);
    return NULL;
  }
  return r;
}

HackRunner *runner_create(Canvas *canvas) {
  return runner_create_with(canvas, g_hacks, g_hack_count);
}

static void stop(HackRunner *r) {
  if (!r->running) return;
  r->hacks[r->index]->free(r->dpy, RUNNER_WINDOW, r->closure);
  r->closure = NULL;
  r->running = 0;
}

void runner_destroy(HackRunner *r) {
  if (!r) return;
  stop(r);
  xshim_close_display(r->dpy);
  free(r);
}

int runner_start(HackRunner *r, int index) {
  if (index < 0 || index >= r->count) return -1;
  stop(r);
  r->index = index;
  canvas_clear(r->canvas, 0);
  xshim_set_defaults(r->hacks[index]->defaults);
  r->closure = r->hacks[index]->init(r->dpy, RUNNER_WINDOW);
  r->running = 1;
  return 0;
}

unsigned long runner_step(HackRunner *r) {
  if (!r->running) return RUNNER_MAX_DELAY_US;
  unsigned long d = r->hacks[r->index]->draw(r->dpy, RUNNER_WINDOW, r->closure);
  if (d < RUNNER_MIN_DELAY_US) return RUNNER_MIN_DELAY_US;
  if (d > RUNNER_MAX_DELAY_US) return RUNNER_MAX_DELAY_US;
  return d;
}

int runner_next(HackRunner *r) {
  runner_start(r, (r->index + 1) % r->count);
  return r->index;
}

int runner_prev(HackRunner *r) {
  runner_start(r, (r->index + r->count - 1) % r->count);
  return r->index;
}

int runner_index(const HackRunner *r) { return r->index; }
# stopwatch-screensaver

xscreensaver "hacks" running on the M5Stack StopWatch (SKU C152, ESP32-S3,
466×466 round AMOLED), through a small X11 shim. A learning project in
embedded development.

Right now it runs five hacks, unmodified from xscreensaver 6.16: **Pyro**
(fireworks), **HyperCube**, **XSpirograph**, **Petri** (mould growth) and
**Helix**, at about 22 fps (the line-heavy ones about 10). The
[porting assessment](docs/porting-assessment.md) rates every other hack by
porting effort.

## How it works

- `firmware/src/core/` is a 466×466 RGB565 canvas with clipped drawing
  primitives, held in PSRAM.
- `firmware/src/x11shim/` implements the Xlib calls hacks use, drawing into
  that canvas, and serves each hack's default settings as its resources.
- `firmware/src/hacks/` holds the copied hack sources. They compile
  unmodified against the shim's own `screenhack.h`.
- `firmware/src/runner/` starts, steps and switches hacks.
- `firmware/src/main.cpp` pushes the canvas to the display each frame and
  handles the buttons.

The same code builds natively on the Mac, which is how the tests run and how
frames are dumped to PNG without any hardware.

## Prerequisites

- macOS with the Xcode command line tools
- [`uv`](https://docs.astral.sh/uv/)
- The StopWatch connected over USB-C

## Setup

Everything installs inside this folder.

```bash
uv run tools/fetch_xscreensaver.py      # downloads xscreensaver into vendor/
uv venv .venv
VIRTUAL_ENV=.venv uv pip install platformio
source tools/env.sh                     # keeps PlatformIO inside this folder
cd firmware
pio test -e native                      # host tests (canvas, shim, hacks)
pio run -e stopwatch -t upload          # build and flash the device
```

The serial port is set in `firmware/platformio.ini`
(`/dev/cu.usbmodem112401`). Change it if your device shows up elsewhere. If
the upload cannot connect, hold the power button for about 2 seconds until
the green LED lights, then try again.

To see a frame without the device:

```bash
cd firmware && pio run -e dump
.pio/build/dump/program 0 900 /tmp/pyro.raw
cd .. && uv run tools/rgb565_to_png.py /tmp/pyro.raw 466 466 /tmp/pyro.png
```

## Controls

Button A starts the next hack and button B the previous one, wrapping
around at either end. The order is Pyro, HyperCube, XSpirograph, Petri, Helix.

## Restoring the original firmware

Flashing replaces the conference firmware. Two ways back:

- **Browser installer:** open <https://workos.com/init/badge/install> in
  desktop Chrome or Edge. This works because the partition table is
  unchanged (`app3M_fat9M_16MB`).
- **Exact restore from a backup:** if you took one before the first flash
  (`backups/stopwatch-original-16MB.bin`, git-ignored), write it back with:

```bash
source tools/env.sh
python .platformio/packages/tool-esptoolpy/esptool.py \
  --port /dev/cu.usbmodem112401 --baud 921600 \
  write_flash 0x0 backups/stopwatch-original-16MB.bin
```

This restores the whole flash, including the badge profile.

## Cleaning up

```bash
rm -rf .venv .platformio firmware/.pio vendor backups
```

## Licence

Our code is MIT licensed (see `LICENSE`). Files copied from xscreensaver
keep their own notices and are listed in `THIRD_PARTY_NOTICES.md`.

